mapper.select:
SELECT p.id, p.name, p.model, CONCAT(#{baseUrl}, p.img_dir, p.main_img) AS mainImg, p.pic_count AS picCount, p.cue_type AS cueType, p.hardness, p.tip_diameter AS tipDiameter, p.weight, p.material, p.spec, p.applicable_scene AS applicableScene, p.params, p.description, p.sales, p.stock, p.status, p.fit_play AS fitPlay, p.fit_power AS fitPower, IF(c.name REGEXP '^[0-9]{2}_', SUBSTRING(c.name, 4), c.name) AS categoryName, b.name AS brandName, pr.official_price AS officialPrice, pr.pdd_price AS pddPrice, pr.platform_price AS platformPrice FROM product p LEFT JOIN category c ON c.id = p.category_id LEFT JOIN brand b ON b.id = p.brand_id LEFT JOIN product_price pr ON pr.product_id = p.id
p.status = 1 AND p.category_id = #{categoryId} AND p.brand_id = #{brandId} AND p.cue_type = #{cueType} AND p.hardness = #{hardness}
AND (p.name LIKE CONCAT('%',#{keyword},'%') OR p.model LIKE CONCAT('%',#{keyword},'%'))
AND pr.platform_price >= #{minPrice} AND pr.platform_price <= #{maxPrice}
ORDER BY
p.sales DESC pr.platform_price ASC pr.platform_price DESC p.create_time DESC p.sort ASC, p.id ASC
